import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';
import { exportCsv } from '../src/export.js';

test('exportCsv returns string', () => {
  const r = exportCsv([]);
  assert.equal(typeof r, 'string');
});

test('exportCsv with empty invoice list', () => {
  const r = exportCsv([]);
  const lines = r.split('\n');
  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
  assert.equal(lines.length, 2);
});

test('exportCsv includes header line', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const csv = exportCsv([issued]);
  assert.ok(csv.startsWith('number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n'));
});

test('exportCsv ends with newline', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const csv = exportCsv([issued]);
  assert.ok(csv.endsWith('\n'));
});

test('exportCsv includes invoice number', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const csv = exportCsv([issued]);
  assert.ok(csv.includes('INV-2025-0001'));
});

test('exportCsv includes customer name', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const csv = exportCsv([issued]);
  assert.ok(csv.includes('Northwind Studio'));
});

test('exportCsv includes dates', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const csv = exportCsv([issued]);
  assert.ok(csv.includes('2025-10-07'));
  assert.ok(csv.includes('2025-10-21'));
});

test('exportCsv includes status', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const csv = exportCsv([issued]);
  assert.ok(csv.includes('issued'));
});

test('exportCsv formats amounts as euros', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;
  const totals = invoiceTotals(issued);

  const csv = exportCsv([issued]);
  const expected = (totals.total / 100).toFixed(2);
  assert.ok(csv.includes(expected));
});

test('exportCsv with decimal amounts', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  const parts = dataLine.split(',');
  assert.ok(parts[5].includes('.'));
});

test('exportCsv escapes fields with comma', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const csv = exportCsv([issued]);
  assert.ok(csv.includes('"Kite & Co"'));
});

test('exportCsv escapes double quotes', () => {
  const invoice = {
    number: 'INV-2025-0001',
    customerId: 'C-001',
    issueDate: '2025-10-07',
    dueDate: '2025-10-21',
    status: 'issued',
    lines: [
      {
        sku: 'DES-HOUR',
        name: 'Design Hours',
        qty: 1,
        unitPrice: 10000,
        vatRate: 21,
      },
    ],
  };

  const csv = exportCsv([invoice]);
  assert.ok(csv.includes('Northwind Studio'));
});

test('exportCsv includes multiple invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const inv1 = issueInvoice(r1.value, []);
  const inv2 = issueInvoice(r2.value, ['INV-2025-0001']);

  const csv = exportCsv([inv1.value, inv2.value]);
  const lines = csv.split('\n');
  assert.equal(lines.length, 4);
  assert.ok(csv.includes('INV-2025-0001'));
  assert.ok(csv.includes('INV-2025-0002'));
});

test('exportCsv includes partially paid amount', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;
  const totals = invoiceTotals(issued);
  const half = Math.floor(totals.total / 2);

  const r3 = recordPayment(issued, { amount: half, date: '2025-10-08' });
  const partially = r3.value;

  const csv = exportCsv([partially]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  const parts = dataLine.split(',');
  const dueAmount = (totals.total - half) / 100;
  assert.equal(parseFloat(parts[9]), dueAmount);
});

test('exportCsv includes 0 due for paid invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;
  const totals = invoiceTotals(issued);

  const r3 = recordPayment(issued, { amount: totals.total, date: '2025-10-08' });
  const paid = r3.value;

  const csv = exportCsv([paid]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  const parts = dataLine.split(',');
  assert.equal(parseFloat(parts[9]), 0);
});

test('exportCsv preserves invoice order', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const inv1 = issueInvoice(r1.value, []);
  const inv2 = issueInvoice(r2.value, ['INV-2025-0001']);
  const inv3 = issueInvoice(r3.value, ['INV-2025-0001', 'INV-2025-0002']);

  const csv = exportCsv([inv1.value, inv2.value, inv3.value]);
  const lines = csv.split('\n');
  assert.ok(lines[1].includes('INV-2025-0001'));
  assert.ok(lines[2].includes('INV-2025-0002'));
  assert.ok(lines[3].includes('INV-2025-0003'));
});

test('exportCsv with discount', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 10 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;
  const totals = invoiceTotals(issued);

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  const parts = dataLine.split(',');
  const discount = parseFloat(parts[6]);
  assert.ok(discount > 0);
});

test('exportCsv with VAT', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;
  const totals = invoiceTotals(issued);

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  const parts = dataLine.split(',');
  const vat = parseFloat(parts[7]);
  assert.equal(vat, totals.vat / 100);
});

test('exportCsv total line count', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');
  assert.equal(lines.length, 3);
});

